    // ★ 只算"可算的那一半"：所有 expectations 里出现的 path，都必须是某个节点的 path。
    //   "debt/steps/OQ 里提到的 src 路径"没法算（那些是散文）⇒ 那句话留在 note 里，不假装算全。
    const need = new Set();
    for (const n of nodes) for (const e of (n.decision?.expectations ?? [])) {
      if (typeof e.path === 'string' && e.path.trim()) need.add(e.path.replace(/\\/g, '/').trim());
    }
    const have = new Set(paths);
    const missing = [...need].filter((p) => !have.has(p));
    return missing.length === 0;
  })()

(() => {
    // ★ 只要【任务系统核心】：写入口（dsl_ops）/ 巡检（patrol）/ 规则（domain）
    //   ★ 不要渲染/画图（bricks / derive / render_* / opl 等）—— 那些是"展示层"，不该被任务系统要求设计。
    const SCOPE = ['src/application/design/dsl_ops/', 'src/application/patrol/', 'src/domain/'];
    const inScope = nodes.filter((n) => SCOPE.some((s) => String(n.description ?? '').replace(/\\/g, '/').startsWith(s)));
    const bad = inScope.filter((n) => {
      const d = n.decision;
      return !d || !String(d.summary ?? '').trim() || !String(d.acceptance ?? '').trim() || (d.expectations ?? []).length < 1;
    });
    return bad.length === 0;
  })()

(() => {
  // ★ kind 白名单（★ 加新 kind 时这里必须同步 —— 2026-10-19 加 source-has 时漏了，D3 立刻红）
  const KINDS = ['file-exists','symbol-exists','signature-matches','edge-exists','edge-absent','call-exists','run','source-has'];
  const bad = [];
  for (const n of nodes) for (const e of (n.decision?.expectations ?? [])) {
    if (!KINDS.includes(e.kind)) bad.push(n.id + ':' + String(e.kind));
  }
  return bad.length === 0;
})()

