  if (!callReport) return false;
  if (callReport.error) return false;
  return callReport.checked >= 1 && callReport.failed === 0 && callReport.unsupported === 0;
})()

(() => {
  // ★ D7 的正解（用户 2026-10-19）：不靠人写反例，靠【系统自动突变】
  //   · 存活（改坏了还 pass）= 装饰判据 ⇒ 必须为 0
  //   · run 类跳过（expect 是任意表达式，改哪个字段会 fail 不可知）⇒ 如实计入 skipped，不假绿
  if (!mutateReport) return false;
  if (mutateReport.error) return false;
  return mutateReport.survived === 0;
})()

(() => {
    // ★★★ 2026-10-19（用户理想："完全不需要人工外力，LLM + 程序内部自洽"）：
    //   原来这条是"外部审查通过"—— 那是人审。现在改成【程序自洽】：
    //   ① 已经跑过的判据里，没有一条 fail（★ results 在求值域里）
    //   ② 自动突变没有存活判据（★ mutateReport.survived === 0）
    //   ③ 至少跑了 5 条（防止"没算就通过"）
    if (!mutateReport) return false;
    if (mutateReport.error) return false;
    const done = (results ?? []).filter(r => r.verdict === 'pass' || r.verdict === 'fail');
    return done.length >= 5 && done.every(r => r.verdict !== 'fail') && mutateReport.survived === 0;
  })()
